export interface Pending<Req> {
  id: number
  request: Req
}

export class DialogQueue<Req, Res> {
  private items: (Pending<Req> & { resolve: (value: Res) => void })[] = []
  private head: Pending<Req> | null = null
  private listeners = new Set<() => void>()
  private nextId = 1

  request = (request: Req): Promise<Res> =>
    new Promise<Res>((resolve) => {
      this.items.push({ id: this.nextId++, request, resolve })
      this.changed()
    })

  /** The request to show now (stable reference until the queue changes). */
  current = (): Pending<Req> | null => this.head

  settle = (id: number, value: Res) => {
    const first = this.items[0]
    if (!first || first.id !== id) return
    this.items.shift()
    first.resolve(value)
    this.changed()
  }

  subscribe = (fn: () => void) => {
    this.listeners.add(fn)
    return () => void this.listeners.delete(fn)
  }

  private changed() {
    const first = this.items[0]
    const next = first ? { id: first.id, request: first.request } : null
    if (next?.id === this.head?.id) return
    this.head = next
    this.listeners.forEach((fn) => fn())
  }
}

/** <form method="dialog"> buttons set returnValue; Esc and other close requests leave it empty. */
export const confirmResult = (returnValue: string) => returnValue === 'confirm'

export function promptResult(returnValue: string, input: string): string | null {
  if (returnValue !== 'confirm') return null
  return input.trim() || null
}
